import axios from "axios";
/**
 * Send GraphQL request to GitHub API.
 *
 * @param data Request data.
 * @param headers Request headers.
 * @returns Request response.
 */
const request = (data, headers) => {
    return axios({
        url: "https://api.github.com/graphql",
        method: "post",
        headers,
        data,
    });
};
export { request };
